/* เวลาขึ้นเครื่อง */
function(){const G=XQG;const pax=G.r(180,360),rA=G.pk([12,15,18,20]),pri=G.r(20,40),rP=G.pk([5,8,10]);const t=Math.ceil(pri/rP)+Math.ceil((pax-pri)/rA);const start=G.r(10,20)*60+G.pk([0,15,30,45]);const ok=start+t;
 const o=G.opt(G.hm(ok),[G.hm(start+Math.ceil(pax/rA)),G.hm(ok+5),G.hm(ok-Math.ceil(pri/rP)),G.hm(ok+10)]);
 return ['เริ่มขึ้นเครื่องเวลา '+G.hm(start)+' ผู้โดยสารกลุ่มพิเศษ '+pri+' คนขึ้นก่อนในอัตรา '+rP+' คนต่อนาที จากนั้นผู้โดยสารที่เหลือขึ้นในอัตรา '+rA+' คนต่อนาที เที่ยวบินมีผู้โดยสาร '+pax+' คน การขึ้นเครื่องจะเสร็จเวลาใด โดยปัดแต่ละช่วงเป็นนาทีเต็ม',o,'กลุ่มพิเศษใช้ '+Math.ceil(pri/rP)+' นาที ที่เหลือ '+(pax-pri)+' คนใช้ '+Math.ceil((pax-pri)/rA)+' นาที รวม '+t+' นาที เสร็จเวลา '+G.hm(ok)]},
/* น้ำดื่ม */
function(){const G=XQG;const pax=G.r(200,380),hr=G.pk([6,8,10,12]),ml=G.pk([150,200,250]),every=G.pk([2]),bot=G.pk([1.5,1]);const tot=pax*ml*(hr/every);const ok=Math.ceil(tot/(bot*1000));
 const o=G.opt(G.nf(ok)+' ขวด',[G.nf(Math.ceil(pax*ml*hr/(bot*1000)))+' ขวด',G.nf(Math.ceil(pax*ml/(bot*1000)))+' ขวด',G.nf(ok+12)+' ขวด',G.nf(Math.max(1,ok-9))+' ขวด']);
 return ['ลูกเรือเสิร์ฟน้ำผู้โดยสารคนละ '+ml+' มล. ทุก '+every+' ชั่วโมง ตลอดเที่ยวบิน '+hr+' ชั่วโมง ผู้โดยสาร '+pax+' คน ต้องใช้น้ำขวดขนาด '+bot+' ลิตรอย่างน้อยกี่ขวด',o,'เสิร์ฟ '+(hr/every)+' รอบ รวม '+G.nf(tot)+' มล. หารด้วย '+G.nf(bot*1000)+' มล. แล้วปัดขึ้นได้ '+ok+' ขวด']},
/* ร้อยละการเปลี่ยนแปลง */
function(){const G=XQG;const a=G.pk([40,50,60,80,120,160,200]),pc=G.pk([15,20,25,30,35,40]);const b=a*(100-pc)/100;if(b%1)return XQ.t2[12]();
 const back=Math.round((a-b)/b*1000)/10;const o=G.opt('ร้อยละ '+pc,['ร้อยละ '+(a-b),'ร้อยละ '+back,'ร้อยละ '+(100-pc),'ร้อยละ '+(pc+5)]);
 return ['เดือนก่อนมีคำร้องเรียนเรื่องอาหาร '+a+' เรื่อง เดือนนี้เหลือ '+b+' เรื่อง จำนวนคำร้องเรียนลดลงร้อยละเท่าใด',o,'ลดลง '+(a-b)+' เรื่องจากเดิม '+a+' เรื่อง คิดเป็น '+(a-b)+' หาร '+a+' คูณ 100 เท่ากับร้อยละ '+pc+' ไม่ใช่การเทียบกับจำนวนใหม่']},
/* ลำดับอาวุโส */
function(){const G=XQG;const N=G.pk([['เมย์','บีม','ฟ้า','ต้น'],['ปาล์ม','แนน','กอล์ฟ','มุก'],['ภูมิ','ขวัญ','ไอซ์','นนท์'],['ปอ','เจน','แบงก์','มายด์']]).slice();
 for(let i=3;i>0;i--){const j=G.r(0,i);[N[i],N[j]]=[N[j],N[i]]}
 const clues=G.pk([[N[0]+' อาวุโสกว่า '+N[2],N[2]+' อาวุโสกว่า '+N[1],N[3]+' อาวุโสกว่า '+N[0]],[N[1]+' อาวุโสน้อยกว่า '+N[2],N[3]+' อาวุโสกว่า '+N[0],N[2]+' อาวุโสน้อยกว่า '+N[0]]]);const order=[N[3],N[0],N[2],N[1]];
 const q=G.r(0,1);const ok=q?order[2]:order[1];
 const o=G.opt(ok,[order[0],order[3],q?order[1]:order[2]]);
 return ['ลูกเรือสี่คนคือ '+N.slice().sort().join(' ')+' ข้อมูลคือ '+clues.join(' และ ')+' ใครอาวุโสเป็นลำดับที่ '+(q?'สาม':'สอง'),o,'เรียงจากอาวุโสมากไปน้อยได้ '+order.join(' ')+' จึงตอบ '+ok]},
