/* ===== v758 แก้บัคหน้าจอซูมค้างในเกมเครื่องบิน (iPhone)
   ระหว่างอยู่ในเกม ล็อกการซูมของหน้า ป้องกันการถ่างนิ้ว และถ้าหน้าถูกซูมค้างไว้ (เช่น สลับแอปแล้วกลับมา) จะคืนขนาดปกติให้อัตโนมัติ ===== */
(function(){const m=document.querySelector('meta[name=viewport]');if(!m)return;const base=m.getAttribute('content')||'width=device-width,initial-scale=1,viewport-fit=cover';
 const LOCK='width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover';let locked=false,busy=0;
 function inGame(){return !!document.querySelector('.flyw')}
 function setLock(on){if(on===locked)return;locked=on;m.setAttribute('content',on?LOCK:base)}
 function zoomed(){const vv=window.visualViewport;return !!(vv&&(vv.scale>1.01||Math.abs(vv.offsetLeft)>1||Math.abs(vv.offsetTop)>1))}
 function reset(force){if(!inGame()||busy)return;if(!force&&!zoomed())return;busy=1;
  m.setAttribute('content',LOCK.replace('initial-scale=1','initial-scale=1.01'));
  setTimeout(()=>{m.setAttribute('content',LOCK);locked=true;try{window.scrollTo(0,0)}catch(e){}try{window.dispatchEvent(new Event('resize'))}catch(e){}busy=0},60)}
 setInterval(()=>{const g=inGame();setLock(g);if(g)reset(false)},600);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden){setTimeout(()=>reset(true),200);setTimeout(()=>reset(false),900)}});
 window.addEventListener('pageshow',()=>setTimeout(()=>reset(true),200));
 window.addEventListener('orientationchange',()=>setTimeout(()=>reset(true),450));
 if(window.visualViewport)visualViewport.addEventListener('resize',()=>{if(inGame()&&zoomed())setTimeout(()=>reset(false),150)});
 ['gesturestart','gesturechange','gestureend'].forEach(t=>document.addEventListener(t,e=>{if(inGame())e.preventDefault()},{passive:false}));
 document.addEventListener('touchmove',e=>{if(inGame()&&e.touches&&e.touches.length>1)e.preventDefault()},{passive:false});
})();

/* ===== v760 แก้บัคปุ่มข้ามคำถามก่อนบิน: ตอบเองไม่ได้
   1) กันปุ่มสลับทำงานซ้ำสองครั้งจากการแตะครั้งเดียว (บนจอสัมผัสจะเหมือนกดแล้วไม่เปลี่ยน)
   2) ระหว่างเปิดข้ามอยู่ แตะคำตอบได้เลย ระบบจะปิดการข้ามให้อัตโนมัติแล้วรับคำตอบนั้นทันที ===== */
(function(){let last=0;
 window.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('.qz-skip');if(!b)return;const n=Date.now();if(n-last<650){e.stopImmediatePropagation();e.preventDefault();return}last=n},true);
 window.addEventListener('click',e=>{const t=e.target;if(!t.closest)return;const d=t.closest('.qsk5-dim');if(!d||t.closest('.qz-skip'))return;
  let on=false;try{on=fwQSkipOn()}catch(x){}if(!on)return;try{localStorage.setItem('fwQSkip','0')}catch(x){}try{toast('ปิดการข้ามแล้ว ตอบคำถามได้ตามปกติ')}catch(x){}
  setTimeout(()=>{document.querySelectorAll('.qz-skip').forEach(k=>{k.classList.remove('on');k.setAttribute('aria-checked','false');const m=k.querySelector('em');if(m)m.textContent='ตอบตามปกติ'});document.querySelectorAll('.qsk5-dim').forEach(x=>x.classList.remove('qsk5-dim'))},30);
  const btn=t.closest('button,[data-l2],[data-act]');if(!btn||btn===d){e.stopImmediatePropagation();e.preventDefault();try{fwL2Go()}catch(x){render()}}},true);
})();
